def solve(record):
    x = record['record_2']
    edges, source, target = x[0], x[1], x[2]
    from collections import deque

    # Build an undirected adjacency list.
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)

    # If start and end are the same, we need a positive-length round trip.
    if source == target:
        visited = {source}
        queue = deque([(source, 0)])          # (node, distance from start)
        while queue:
            node, dist = queue.popleft()
            for nbr in adj.get(node, []):
                if nbr == source:
                    return dist + 1
                if nbr not in visited:
                    visited.add(nbr)
                    queue.append((nbr, dist + 1))
        return -1

    # Distinct start and end: ordinary shortest path.
    if source not in adj or target not in adj:
        return -1

    visited = {source}
    queue = deque([(source, 0)])
    while queue:
        node, dist = queue.popleft()
        if node == target:
            return dist
        for nbr in adj.get(node, []):
            if nbr not in visited:
                visited.add(nbr)
                queue.append((nbr, dist + 1))
    return -1
